var room = 1;

function education_fields() {

    room++;
    var objTo = document.getElementById('education_fields')
    var divtest = document.createElement("div");
    divtest.setAttribute("class", "form-group mb-0 removeclass" + room);
    var rdiv = 'removeclass' + room;
    divtest.innerHTML = '<div class="row">  <div class="col-sm-10"><div class="form-group mb-1">   <input type="file" class="form-control" id="Degree" name="Degree[]" value="" placeholder="Degree"></div></div>  <div class="col-sm-2"><div class="form-group">  <div class="input-group">  <div class="input-group-append">  <button class="btn btn-danger" type="button" onclick="remove_education_fields(' + room + ');">  <i class="fa fa-minus"></i> </button></div></div></div></div><div class="clear"></div></row>';

    objTo.appendChild(divtest)
}

function remove_education_fields(rid) {
    $('.removeclass' + rid).remove();
}

